def _validate_regression_wave_min_hit_rate_drop(
    regression_wave_min_hit_rate_drop: Any,
) -> tuple[int, int]:
    """Validate the regression wave minimum hit-rate drop threshold.

    Used only by
    :meth:`lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regressions`,
    before any state lookup:
    ``regression_wave_min_hit_rate_drop`` must be a tuple (else
    :class:`TypeError`) of exactly two non-``bool`` :class:`int`
    values (a ``bool`` or non-:class:`int` element raises
    :class:`TypeError`); a wrong element count, a negative
    numerator, a non-positive denominator or a numerator exceeding
    the denominator raises :class:`ValueError`.
    """
    if not isinstance(regression_wave_min_hit_rate_drop, tuple):
        raise TypeError(
            f"regression_wave_min_hit_rate_drop must be a tuple, "
            f"got {type(regression_wave_min_hit_rate_drop).__name__}"
        )
    if len(regression_wave_min_hit_rate_drop) != 2:
        raise ValueError(
            f"regression_wave_min_hit_rate_drop must have exactly "
            f"2 elements, got {len(regression_wave_min_hit_rate_drop)}"
        )
    numerator, denominator = regression_wave_min_hit_rate_drop
    for position, part in enumerate(regression_wave_min_hit_rate_drop):
        name = f"regression_wave_min_hit_rate_drop[{position}]"
        if isinstance(part, bool) or not isinstance(part, int):
            raise TypeError(
                f"{name} must be an int, got {type(part).__name__}"
            )
    if numerator < 0:
        raise ValueError(
            "regression_wave_min_hit_rate_drop numerator must be "
            "non-negative"
        )
    if denominator < 1:
        raise ValueError(
            "regression_wave_min_hit_rate_drop denominator must be "
            "positive"
        )
    if numerator > denominator:
        raise ValueError(
            "regression_wave_min_hit_rate_drop numerator must not "
            "exceed the denominator"
        )
    return (numerator, denominator)

@staticmethod
def _validate_drift_scan_split_cutoffs(
    split_cutoffs: Any,
) -> tuple[int, ...]:
    """Validate the scan split tuple's types and strict ordering.

    Used only by :meth:`lifetime_churn_forecast_drift_scan`, before
    any state lookup: ``split_cutoffs`` must be a tuple (else
    :class:`TypeError`) of non-``bool`` :class:`int` values (a
    ``bool`` or non-:class:`int` element raises
    :class:`TypeError`); a duplicate or non-strictly-increasing
    element raises :class:`ValueError`. An empty tuple is legal.
    Membership in the requested cutoffs is settled by
    :meth:`_validate_drift_scan_splits`.
    """
    if not isinstance(split_cutoffs, tuple):
        raise TypeError(
            f"split_cutoffs must be a tuple, got "
            f"{type(split_cutoffs).__name__}"
        )
    validated: list[int] = []
    previous: int | None = None
    for position, split_cutoff in enumerate(split_cutoffs):
        name = f"split_cutoffs[{position}]"
        if isinstance(split_cutoff, bool) or not isinstance(
            split_cutoff, int
        ):
            raise TypeError(
                f"{name} must be an int, got "
                f"{type(split_cutoff).__name__}"
            )
        if previous is not None and split_cutoff <= previous:
            raise ValueError(
                "split_cutoffs must be strictly increasing"
            )
        previous = split_cutoff
        validated.append(split_cutoff)
    return tuple(validated)

